SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET CONCAT_NULL_YIELDS_NULL ON; SET ARITHABORT ON; SET NUMERIC_ROUNDABORT OFF; SET XACT_ABORT ON; BEGIN TRANSACTION;
DECLARE @s nvarchar(max)=N''; SELECT @s+=N'ALTER TABLE '+QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N' NOCHECK CONSTRAINT ALL;' FROM sys.tables WHERE is_ms_shipped=0; EXEC(@s);
DECLARE @t nvarchar(517); DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT QUOTENAME(SCHEMA_NAME(t.schema_id))+N'.'+QUOTENAME(t.name) FROM sys.tables t WHERE t.is_ms_shipped=0 AND t.name NOT IN ('tbl_BirthDetails','tbl_ChartResults') AND EXISTS(SELECT 1 FROM sys.columns x WHERE x.object_id=t.object_id AND x.name IN ('BirthDetailId','ChartResultId')); OPEN c; FETCH NEXT FROM c INTO @t; WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DELETE FROM '+@t); FETCH NEXT FROM c INTO @t; END CLOSE c; DEALLOCATE c; DELETE FROM dbo.tbl_ChartResults; DELETE FROM dbo.tbl_BirthDetails;
SELECT 'BirthDetails',COUNT(*) FROM dbo.tbl_BirthDetails UNION ALL SELECT 'ChartResults',COUNT(*) FROM dbo.tbl_ChartResults;
SELECT @s=N''; SELECT @s+=N'ALTER TABLE '+QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N' WITH NOCHECK CHECK CONSTRAINT ALL;' FROM sys.tables WHERE is_ms_shipped=0; EXEC(@s); COMMIT;